actions.script:
const L = (text) => ec.l10n.localize(text)
const out = ec.service.sync().name('org.moqui.impl.VoiceServices.get#VoiceStatus').requireNewTransaction(true).disableAuthz().call() || {}
const caps = out.capabilities || {}
const REASONS = {notBuilt: L('This server is not built with SIP (the sip feature).'),
    notConfigured: L('No SIP listener is set: set sip_port or sip_tls_port.'), noTrunk: L('No trunk is set up: add one under Trunks.'),
    noSipServer: L('No SIP server is running in the cluster.'), trunkFailed: L('Every trunk failed: see Trunks for the last error.')}
const yesNo = (value) => (value ? L('Yes') : L('No'))
capabilityList = [
    {name: L('Supported'), value: yesNo(caps.supported)},
    {name: L('Configured'), value: yesNo(caps.configured)},
    {name: L('Active'), value: yesNo(caps.active)},
    {name: L('Emergency calls ready'), value: yesNo(caps.emergencyReady)},
    {name: L('Phone calls going'), value: String(out.activePhoneCalls || 0)},
]
statusActive = !!caps.active
reasonText = caps.active ? '' : REASONS[caps.reasonCode] || L('Phone calls are not available.')
const when = (millis) => (millis ? ec.l10n.format(new Date(Number(millis)), 'MMM d, h:mm:ss a') : '')
sipNodeList = Array.from(out.sipNodeList || []).map((n) => ({instanceId: n.instanceId, sipAddress: n.sipAddress || '',
    tlsAddress: n.tlsAddress || '', rtpPorts: n.rtpPorts || '', heartbeatText: when(n.heartbeatDate), stateText: n.live ? L('Up') : L('Not heard from')}))
mediaNodeList = Array.from(out.mediaNodeList || []).map((n) => ({instanceId: n.instanceId, mediaAddress: n.mediaAddress || '',
    heartbeatText: when(n.heartbeatDate), stateText: !n.live ? L('Not heard from') : n.draining ? L('Draining') : L('Up')}))
ec.message.clearErrors()
